mapper.update:
UPDATE match_bid
SET status = 'ACCEPTED'
WHERE match_id = #{matchId}
AND lawyer_id = #{lawyerId}
AND status = 'PENDING'
AND deleted = 1

UPDATE match_bid
SET
    status = 'REJECTED',
    message = #{message}
WHERE match_id = #{matchId}
AND lawyer_id = #{lawyerId}
AND status = 'PENDING'
AND deleted = 1

UPDATE `match`
SET status = #{status}
WHERE id = #{matchId}
AND match_type = 'DIRECT'
AND deleted = 1
